mapper.update:
UPDATE fairs
   SET status = 'EXPIRED'
     , updated_at = #{now}
 WHERE fair_id = #{fairId}
   AND status = 'PAYMENT_PENDING'
   AND payment_due_at IS NOT NULL
   AND payment_due_at <= #{now}

UPDATE fairs
   SET status = 'IN_PROGRESS'
     , updated_at = #{now}
 WHERE fair_id = #{fairId}
   AND status = 'PREPARING'

UPDATE fairs
   SET status = 'ENDED'
     , updated_at = #{now}
 WHERE fair_id = #{fairId}
   AND status = 'IN_PROGRESS'
